const layer=()=>{
  if(typeof language==='undefined'||language!=='de')return;
  document.documentElement.lang='de';
  document.querySelectorAll('[data-fr]').forEach(e=>{
    const d=e.dataset.de||tr(e.dataset.fr);
    if(d!=null)e.innerHTML=d;else if(e.dataset.en)e.innerHTML=e.dataset.en;else e.innerHTML=e.dataset.fr;
  });
  document.querySelectorAll('[data-alt-fr]').forEach(e=>{const d=tr(e.dataset.altFr);if(d)e.alt=d});
  document.querySelectorAll('[data-aria-fr]').forEach(e=>{const d=tr(e.dataset.ariaFr);if(d)e.setAttribute('aria-label',d)});
  document.querySelectorAll('[data-group-fr]').forEach(e=>{const d=tr(e.dataset.groupFr);if(d)e.setAttribute('aria-label',d)});
  const sw=document.querySelector('.language-switch');if(sw)sw.setAttribute('aria-label','Sprache wählen');
};
const orig=applyLang;
applyLang=function(){orig();layer()};
window.deLayer=layer;
